with original as (select id from public.financial_events where household_id='be772ffd-3ab5-41d5-8438-647a79a553da') select jsonb_build_object('eventCount',(select count(*) from original),'events',(select md5(coalesce(jsonb_agg(to_jsonb(f) order by f.id)::text,'')) from public.financial_events f where id in(select id from original)),'allocations',(select md5(coalesce(jsonb_agg(to_jsonb(a) order by a.id)::text,'')) from public.financial_allocations a where financial_event_id in(select id from original)),'ledger',(select md5(coalesce(jsonb_agg(to_jsonb(l) order by l.id)::text,'')) from public.ledger_entries l where financial_event_id in(select id from original)),'claimedStorage',(select md5(coalesce(jsonb_agg(to_jsonb(o) order by o.id)::text,'')) from storage.objects o where bucket_id='household-files' and name in(select receipt_path from public.financial_events where id in(select id from original)))) as snapshot;
